3:  * submits, then hands Phoenix's answer to `settleRefundCommand` (the toast
4:  * in the module's wording, and the scope's stale queries); the component
5:  * only says what happens next — close a dialog, show a refusal, or ask the
6:  * refund-or-forfeit choice after an issue on `refund`.
7:  */
8: import { type QueryClient, useQueryClient } from "@tanstack/svelte-query";
9: import type { RemoteFormField } from "$app/server";
10: import { toast } from "svelte-sonner";
11: import {
12: 	type RefundCommandResult,
13: 	settleRefundCommand,
14: } from "#lib/beginners-workshops/refunds/outcome.js";
15: import type { RefundScope } from "#lib/beginners-workshops/refunds/scope.js";
16: import type { RefundCommand } from "#lib/beginners-workshops/refunds/wording.js";
17: 
18: /** A note control's attributes, `fields.note.as("text")` of either scope's form. */
19: export type NoteProps = ReturnType<RemoteFormField<string>["as"]>;
20: 
21: /** What the adapter reads of a submitted remote-form instance. */
22: type SubmittedForm = {
23: 	submit(): Promise<boolean>;
24: 	readonly result: RefundCommandResult | undefined;
25: };
26: 
27: export type RefundSubmitHandlers = {
28: 	/** The command succeeded (after the toast and invalidation). */
29: 	done?: () => void;
30: 	/** Phoenix refused it without naming a control. */
31: 	failed?: (error: string) => void;
32: 	/** The submission came back with field issues. */
33: 	invalid?: () => void;
34: };
35: 
36: /**
37:  * The query client a success in `scope` invalidates: the page's for the
38:  * Waitlist tab, none for the console. Call during component setup.
39:  */
40: export function scopeQueryClient(
41: 	scope: RefundScope,
42: 	queryClient?: QueryClient,
43: ): QueryClient | null {
44: 	if (scope.kind !== "person") return null;
45: 	return queryClient ?? useQueryClient();
46: }
47: 
48: export function refundSubmit(
49: 	scope: RefundScope,
50: 	command: RefundCommand,
51: 	queryClient: QueryClient | null,
52: 	handlers: RefundSubmitHandlers = {},
53: ) {
54: 	return async (instance: SubmittedForm) => {
55: 		if (!(await instance.submit())) {
56: 			handlers.invalid?.();
57: 			return;
58: 		}
59: 		const result = instance.result;
60: 		if (!result) return;
61: 		const settled = await settleRefundCommand(scope, command, result, {
62: 			notify: toast,
63: 			queryClient,
64: 		});
65: 		if (settled.ok) handlers.done?.();
66: 		else handlers.failed?.(settled.error);
67: 	};
68: }

