1: <!--
2: 	The Email templates tab of Beginners' Workshops (ALE-383): every Intake
3: 	Email type grouped by kind, with when it is sent and who receives it, and
4: 	the selected type's editor. Templates are
5: 	read and saved through the generated Phoenix client.
6: -->
7: <script lang="ts">
8: import {
9: 	beginnersWorkshopEmailTemplatesListOptions,
10: 	beginnersWorkshopEmailTemplatesListQueryKey,
11: 	beginnersWorkshopEmailTemplatesUpdateMutation,
12: 	type BeginnersWorkshopEmailTemplatesListResponse,
13: 	type IntakeEmailTemplateUpdate,
14: 	type IntakeEmailType,
15: } from "@dhc/api-client";
16: import {
17: 	createMutation,
18: 	createQuery,
19: 	useQueryClient,
20: } from "@tanstack/svelte-query";
21: import { toast } from "svelte-sonner";
22: import { type ApiProblem, apiProblem } from "#lib/api-error.js";
23: import {
24: 	INTAKE_EMAIL_KIND_GROUPS,
25: 	INTAKE_EMAIL_TYPES,
26: } from "#lib/beginners-workshops/intake-emails/presentation.js";
27: import * as Alert from "#lib/components/ui/alert/index.js";
28: import { Button } from "#lib/components/ui/button/index.js";
29: import { Skeleton } from "#lib/components/ui/skeleton/index.js";
30: import { Label } from "#lib/components/ui/label/index.js";
31: import * as NativeSelect from "#lib/components/ui/native-select/index.js";
32: import { cn } from "#lib/utils.js";
33: import IntakeEmailTemplateEditor from "./intake-email-template-editor.svelte";
34: 
35: const queryClient = useQueryClient();
36: const templates = createQuery(() =>
37: 	beginnersWorkshopEmailTemplatesListOptions(),
38: );
39: 
40: let selectedType = $state<IntakeEmailType | null>(null);
41: let problem = $state<ApiProblem | null>(null);
42: 
43: const rows = $derived(templates.data?.data ?? []);
44: const selected = $derived(
45: 	rows.find((row) => row.emailType === selectedType) ?? rows[0],
46: );
47: 
48: const save = createMutation(() => ({
49: 	...beginnersWorkshopEmailTemplatesUpdateMutation(),
50: 	onSuccess: (response) => {
51: 		problem = null;
52: 		const saved = response.data;
53: 		queryClient.setQueryData<BeginnersWorkshopEmailTemplatesListResponse>(
54: 			beginnersWorkshopEmailTemplatesListQueryKey(),
55: 			(current) =>
56: 				current && {
57: 					...current,
58: 					data: current.data.map((row) =>
59: 						row.emailType === saved.emailType ? saved : row,
60: 					),
61: 				},
62: 		);
63: 		toast.success(`${saved.label} saved. Emails queued from now on use it.`);
64: 	},
65: 	onError: (error) => {
66: 		problem = apiProblem(error) ?? {
67: 			detail: "The template could not be saved.",
68: 			fields: [],
69: 		};
70: 	},
71: }));
72: 
73: function pick(type: IntakeEmailType) {
74: 	selectedType = type;
75: 	problem = null;
76: }
77: 
78: function onsave(draft: IntakeEmailTemplateUpdate) {
79: 	if (!selected) return;
80: 	save.mutate({ path: { emailType: selected.emailType }, body: draft });
81: }
82: 
83: const detailClass = (current: boolean) =>
84: 	cn(
85: 		"text-xs font-normal",
86: 		current ? "text-foreground" : "text-muted-foreground",
87: 	);
88: </script>
89: 
90: <div class="flex h-full min-h-0 flex-col gap-4 pb-1">
91: 	<header class="shrink-0 border-b border-border px-1 py-4">
92: 		<h2 class="font-heading text-2xl">Workshop emails</h2>
93: 		<p class="mt-1 max-w-3xl text-sm leading-6 text-muted-foreground">
94: 			One club-wide template per email. Each workshop's details fill the
95: 			placeholders, and the app adds the link button.
96: 		</p>
97: 	</header>
98: 
99: 	{#if templates.isPending}
100: 		<div
101: 			class="grid min-h-0 flex-1 gap-4 lg:grid-cols-[20rem_minmax(0,1fr)]"
102: 			aria-label="Loading email templates"
103: 			role="status"
104: 		>
105: 			<Skeleton class="hidden h-full lg:block" />
106: 			<Skeleton class="h-full" />
107: 		</div>
108: 	{:else if templates.isError}
109: 		<Alert.Root variant="destructive">
110: 			<Alert.Title>Templates unavailable</Alert.Title>
111: 			<Alert.Description>
112: 				{apiProblem(templates.error)?.detail ??
113: 					"The templates could not be loaded."}
114: 			</Alert.Description>
115: 		</Alert.Root>
116: 	{:else if selected}
117: 		<div
118: 			class="grid min-h-0 flex-1 grid-rows-[auto_minmax(0,1fr)] gap-4 lg:grid-cols-[20rem_minmax(0,1fr)] lg:grid-rows-1"
119: 		>
120: 			<div class="grid shrink-0 gap-2 lg:hidden">
121: 				<Label for="intake-email-type">Email template</Label>
122: 				<NativeSelect.Root
123: 					id="intake-email-type"
124: 					value={selected.emailType}
125: 					onchange={(event) =>
126: 						pick(event.currentTarget.value as IntakeEmailType)}
127: 					class="w-full [&_select]:h-11"
128: 				>
129: 					{#each INTAKE_EMAIL_KIND_GROUPS as group (group.kind)}
130: 						<NativeSelect.OptGroup label={group.title}>
131: 							{#each rows.filter((row) => row.kind === group.kind) as row (row.emailType)}
132: 								<NativeSelect.Option value={row.emailType}
133: 									>{row.label}</NativeSelect.Option
134: 								>
135: 							{/each}
136: 						</NativeSelect.OptGroup>
137: 					{/each}
138: 				</NativeSelect.Root>
139: 			</div>
140: 			<nav
141: 				class="hidden min-h-0 flex-col gap-5 overflow-y-auto rounded-2xl border border-border bg-card p-3 lg:flex"
142: 				aria-label="Email types"
143: 			>
144: 				{#each INTAKE_EMAIL_KIND_GROUPS as group (group.kind)}
145: 					<section class="flex shrink-0 flex-col gap-2">
146: 						<h3
147: 							class="px-3 py-1 text-xs font-bold tracking-wider text-foreground uppercase"
148: 						>
149: 							{group.title}
150: 						</h3>
151: 						{#each rows.filter((row) => row.kind === group.kind) as row (row.emailType)}
152: 							{@const copy = INTAKE_EMAIL_TYPES[row.emailType]}
153: 							{@const current = row.emailType === selected.emailType}
154: 							<Button
155: 								type="button"
156: 								variant="outline"
157: 								class={cn(
158: 									"h-auto w-full flex-col items-start gap-1 px-3 py-3 text-left whitespace-normal shadow-none hover:text-foreground",
159: 									current
160: 										? "border-primary bg-primary/10 text-foreground hover:bg-primary/15"
161: 										: "border-transparent bg-transparent hover:border-border hover:bg-muted/50",
162: 								)}
163: 								aria-current={current ? "true" : undefined}
164: 								onclick={() => pick(row.emailType)}
165: 							>
166: 								<span class="font-medium">{row.label}</span>
167: 								<span class={detailClass(current)}>
168: 									{copy.sentWhen}
169: 								</span>
170: 								<span class={detailClass(current)}>
171: 									To: {copy.recipients}
172: 								</span>
173: 							</Button>
174: 						{/each}
175: 					</section>
176: 				{/each}
177: 			</nav>
178: 
179: 			{#key `${selected.emailType}:${selected.updatedAt}`}
180: 				<IntakeEmailTemplateEditor
181: 					template={selected}
182: 					{onsave}
183: 					saving={save.isPending}
184: 					{problem}
185: 				/>
186: 			{/key}
187: 		</div>
188: 	{/if}
189: </div>

