42: import WithdrawDialog from "#lib/components/beginners-workshops/refunds/withdraw-dialog.svelte";
43: import { formatDublinInstant } from "#lib/club-calendar.js";
44: import { Badge } from "#lib/components/ui/badge/index.js";
45: import { Button } from "#lib/components/ui/button/index.js";
46: import * as Field from "#lib/components/ui/field/index.js";
47: import { Textarea } from "#lib/components/ui/textarea/index.js";
48: import {
49: 	correctAttendanceSchema,
50: 	intakeCommandSchema,
51: } from "#lib/schemas/beginnersWorkshop.js";
52: import { correctAttendance, runIntakeCommand } from "./console.remote";
