9: 	BeginnersWorkshopStaffCandidate,
10: } from "@dhc/api-client";
11: import { toast } from "svelte-sonner";
12: import { formatCivilDate } from "#lib/club-calendar.js";
13: import { Button } from "#lib/components/ui/button/index.js";
14: import * as Dialog from "#lib/components/ui/dialog/index.js";
15: import WorkshopDialog from "#lib/components/beginners-workshops/workshop-dialog.svelte";
16: import { workshopStaffSchema } from "#lib/schemas/beginnersWorkshop.js";
17: import StaffPickers from "./staff-pickers.svelte";
18: import { setWorkshopStaff } from "./workshops.remote";
19: 
20: let {
21: 	workshop,
22: 	candidates,
23: 	open = $bindable(false),
24: }: {
25: 	workshop: BeginnersWorkshop;
26: 	candidates: BeginnersWorkshopStaffCandidate[];
27: 	open?: boolean;
28: } = $props();
29: 
30: const form = $derived(setWorkshopStaff.for(workshop.id));
31: // The dialog is keyed by workshop, so its picks start from that workshop.
32: // svelte-ignore state_referenced_locally
33: let coach = $state(workshop.staff.coach?.principalId ?? "");
34: // svelte-ignore state_referenced_locally
35: let assistants = $state(
36: 	workshop.staff.assistants.map((assistant) => assistant.principalId),
37: );
38: let formError = $state<string | null>(null);
39: </script>
40: 
41: <Dialog.Root bind:open>
42: 	<WorkshopDialog>
43: 		<Dialog.Header>
44: 			<Dialog.Title>Staff for {formatCivilDate(workshop.date)}</Dialog.Title>
45: 			<Dialog.Description>
46: 				Assigned staff can access this workshop’s check-in screen immediately.
47: 				Attendees are not emailed about staff changes.
48: 			</Dialog.Description>
49: 		</Dialog.Header>
50: 
51: 		<form
52: 			{...form.preflight(workshopStaffSchema).enhance(async (instance) => {
53: 				formError = null;
54: 				if (!(await instance.submit())) return;
55: 				const result = instance.result;
56: 				if (result?.ok) {
57: 					toast.success("Staff saved");
58: 					open = false;
59: 				} else if (result) {
60: 					formError = result.error;
61: 				}
62: 			})}
63: 			class="grid gap-5"
64: 			aria-label="Workshop Staff"
65: 		>
66: 			<input {...form.fields.id.as("hidden", workshop.id)} />
67: 			{#if coach}
68: 				<input {...form.fields.coachPrincipalId.as("hidden", coach)} />
69: 			{/if}
70: 			{#each assistants as assistant, index (assistant)}
71: 				<input
72: 					{...form.fields.assistantPrincipalIds[index].as("hidden", assistant)}
73: 				/>
74: 			{/each}
75: 
76: 			<StaffPickers
77: 				idPrefix={`staff-${workshop.id}`}
78: 				{candidates}
79: 				current={workshop.staff}
80: 				bind:coach
81: 				bind:assistants
82: 				coachIssues={form.fields.coachPrincipalId.issues() ?? []}
83: 				assistantIssues={form.fields.assistantPrincipalIds.issues() ?? []}
84: 			/>
85: 
86: 			{#if formError}
87: 				<p class="text-sm text-destructive" role="alert">{formError}</p>
88: 			{/if}
89: 
90: 			<Dialog.Footer>
91: 				<Button type="button" variant="outline" onclick={() => (open = false)}
92: 					>Cancel</Button
93: 				>
94: 				<Button type="submit" disabled={!!form.pending}
95: 					>{form.pending ? "Saving…" : "Save Staff"}</Button
96: 				>
97: 			</Dialog.Footer>
98: 		</form>
99: 	</WorkshopDialog>
100: </Dialog.Root>

